-- Idempotent install for rootcause.detection_paths
-- Auto-generated from dbanalytics_install.backup. Safe to re-run (psql -f).

CREATE SCHEMA IF NOT EXISTS rootcause;

CREATE SEQUENCE IF NOT EXISTS rootcause.detection_paths_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE IF NOT EXISTS rootcause.detection_paths (
    id integer NOT NULL,
    root_cause_id character varying(40) NOT NULL,
    vendor_slug character varying(50) NOT NULL,
    name character varying(300) NOT NULL,
    description text,
    path_type character varying(50) DEFAULT 'diagnostic'::character varying NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    min_version character varying(20),
    max_version character varying(20),
    superseded_by_id integer,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL
);

ALTER TABLE rootcause.detection_paths ALTER COLUMN id SET DEFAULT nextval('rootcause.detection_paths_id_seq'::regclass);
ALTER SEQUENCE rootcause.detection_paths_id_seq OWNED BY rootcause.detection_paths.id;

-- data: load only into a freshly-created (empty) table
DROP TABLE IF EXISTS _stg_load;
CREATE TEMP TABLE _stg_load (LIKE rootcause.detection_paths);
SELECT id, root_cause_id, vendor_slug, name, description, path_type, is_active, min_version, max_version, superseded_by_id, created_at, updated_at FROM _stg_load
WHERE NOT EXISTS (SELECT 1 FROM rootcause.detection_paths);
DROP TABLE _stg_load;

SELECT setval('rootcause.detection_paths_id_seq', GREATEST((SELECT COALESCE(max(id),0) FROM rootcause.detection_paths),1), (SELECT count(*) FROM rootcause.detection_paths) > 0);

DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'rootcause' AND c.relname = 'detection_paths'
          AND con.conname = 'detection_paths_pkey') THEN
        ALTER TABLE ONLY rootcause.detection_paths
    ADD CONSTRAINT detection_paths_pkey PRIMARY KEY (id);
    END IF;
END $do$;
DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'rootcause' AND c.relname = 'detection_paths'
